-- ---------------------------------------------------------------------------
-- Teacher-issued Free Cards (services/class-student-fee-service.ts,
-- app/api/payments/fees/free-cards/route.ts): a 100% waiver of one
-- "ClassStudentFee" row (student, class, month).
--
-- ADDITIVE ONLY: three new columns on "ClassStudentFee" (existing rows get
-- "freeCard" = false and NULLs), one index, one foreign key to "Teacher"
-- (ON DELETE SET NULL) and two CHECKs. No existing row or column is changed.
-- Generated by `prisma migrate diff` from schema.prisma; the CHECKs and the
-- lock timeout are hand-written.
--
-- Deploy order: after 20261119120000_add_email_delivery_tracking and BEFORE
-- the code that reads "freeCard" (every fee query selects it).
-- Guarded by tests/fee-waiver/free-card-migration-guard.test.cjs.
-- ---------------------------------------------------------------------------

-- MANUAL: fail instead of waiting indefinitely for a lock on
-- "ClassStudentFee" or "Teacher". Session-level SET (not SET LOCAL): it works
-- whether Prisma runs this script as one implicit transaction or statement by
-- statement (SET LOCAL would have no effect in the latter). RESET at the end
-- restores the default for the rest of the session; if the script fails
-- inside a transaction, the SET is rolled back with it.
-- See docs/lecture-attendance.md ("Lock timeout").
SET lock_timeout = '5s';

-- AlterTable
ALTER TABLE "ClassStudentFee" ADD COLUMN     "freeCard" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "freeCardIssuedAt" TIMESTAMP(3),
ADD COLUMN     "freeCardIssuedByTeacherId" TEXT;

-- CreateIndex
CREATE INDEX "ClassStudentFee_freeCardIssuedByTeacherId_idx" ON "ClassStudentFee"("freeCardIssuedByTeacherId");

-- AddForeignKey
ALTER TABLE "ClassStudentFee" ADD CONSTRAINT "ClassStudentFee_freeCardIssuedByTeacherId_fkey" FOREIGN KEY ("freeCardIssuedByTeacherId") REFERENCES "Teacher"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Hand-written: a fee with an active Free Card is never payable. Any write
-- that would give it a non-zero finalAmount fails instead of silently
-- charging the student.
ALTER TABLE "ClassStudentFee" ADD CONSTRAINT "ClassStudentFee_freeCard_finalAmount_check"
  CHECK ("freeCard" = false OR "finalAmount" = 0);

-- Hand-written: issue details exist only while the card is active.
ALTER TABLE "ClassStudentFee" ADD CONSTRAINT "ClassStudentFee_freeCard_issued_check"
  CHECK ("freeCard" = true OR ("freeCardIssuedAt" IS NULL AND "freeCardIssuedByTeacherId" IS NULL));

-- MANUAL: restore the default lock timeout for the rest of the session.
RESET lock_timeout;
